// AuroraRevit v1.8.3 educational template: Find Beams with No Structural Usage
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_StructuralFraming);
    var beams = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_StructuralFraming).WhereElementIsNotElementType().ToElements();
    var missing = beams.Where(x => string.IsNullOrWhiteSpace(x.LookupParameter("Structural Usage")?.AsValueString())).ToList();
}

