// AuroraRevit v1.8.3 educational template: Count Structural Framing by Type
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_StructuralFraming);
    var framing = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_StructuralFraming).WhereElementIsNotElementType().ToElements();
    var counts = framing.GroupBy(x => x.GetTypeId()).Select(g => new { TypeId = g.Key, Count = g.Count() }).ToList();
}

