using System.Linq;

// AuroraRevit v1.8.3 educational template: Find Beams Above Level 2
// This template is intentionally read-only or creates a single named view/schedule.
public static void Run(Document doc)
{
    var category = new ElementId(BuiltInCategory.OST_StructuralFraming);
    var level = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().FirstOrDefault(x => x.Name == "Level 2");
    if (level == null) return;
    var beams = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_StructuralFraming).WhereElementIsNotElementType().Where(x => (x.Location as LocationCurve)?.Curve?.GetEndPoint(0).Z > level.Elevation).ToList();
}

